// 1. Get the list of results from the API response
const grants = $input.first().json.results;

// 2. Turn each grant into its own separate item
return grants.map(grant => ({ json: grant }));

values.content:
=Please analyze this EU Funding Call:

**Topic/Title:** {{ $json.content }}

**Programme/Type of Action:** {{ $json.metadata.actions }}

**Specific Scope & Expected Outcomes:** {{ $json.metadata.descriptionByte[0] }}

Based on this text, generate the JSON output as requested in the system instructions.

parameters.jsonBody:
={
  "type": "message",
  "attachments": [
    {
      "contentType": "application/vnd.microsoft.card.adaptive",
      "content": {
        "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
        "type": "AdaptiveCard",
        "version": "1.4",
        "body": [
          {
            "type": "TextBlock",
            "text": "🚨 New Grant Opportunity",
            "weight": "Bolder",
            "size": "Medium"
          },
          {
            "type": "FactSet",
            "facts": [
              {
                "title": "Title:",
                "value": "{{ $json.output[0].content[0].text.title }}"
              },
{
                "title": "Programme:",
                "value": "{{ $json.output[0].content[0].text["programme/type of action"] }}"
              },
              {
                "title": "Score:",
                "value": "{{ $json.output[0].content[0].text.score }}/10"
              },
              {
                "title": "Deadline:",
                "value": "{{ $('Process Grants in Batches').item.json.metadata.deadlineDate[0] }}"
              }
            ]
          },
          {
            "type": "TextBlock",
            "text": "{{ $json.output[0].content[0].text.summary }}",
            "wrap": true
          }
        ],
        "actions": [
          {
            "type": "Action.OpenUrl",
            "title": "View Call",
            "url": "{{ $('Filter Active Grants').item.json.url }}"
          }
        ]
      }
    }
  ]
}
